/** Successful canonical bytes from an explicit build-only run; never complete test coverage. */
import assert from 'node:assert/strict';
import {randomUUID}from'node:crypto';
import {installHash,installJson,INSTALL_BUILD_FIELDS,validateInstallGrant}from'./ci-install-grant.mjs';
import {CI_POLICY}from'./policy-version.mjs';
import {BUILD_ARTIFACT,BUILD_ZIP_MAX}from'./build-artifact.mjs';
import {REPOSITORY,REPOSITORY_ID,WORKFLOW_ID,WORKFLOW_PATH}from'./release-policy.mjs';
import {NEXT_APPLICATION_STATE}from'./next-application-cache-protocol.mjs';
export function inspectBuildOnlySnapshot({run,jobs,artifacts,expected,now=Date.now()}){
 assert(expected.candidate===expected.controller&&/^[a-f0-9]{40}$/.test(expected.candidate??'')&&Number.isSafeInteger(expected.runId)&&expected.runId>0,'Exact trusted alpha candidate/controller required');
 assert(run.id===expected.runId&&run.repository?.id===REPOSITORY_ID&&run.repository.full_name===REPOSITORY&&run.head_repository?.id===REPOSITORY_ID&&run.workflow_id===WORKFLOW_ID&&run.path===WORKFLOW_PATH&&run.head_sha===expected.controller&&run.head_branch==='alpha'&&run.event==='workflow_dispatch'&&run.status==='completed'&&run.conclusion==='success'&&run.run_attempt===1,'Actual successful trusted build-only run required');
 const began=Date.parse(run.created_at),ended=Date.parse(run.updated_at);assert(Number.isFinite(began)&&Number.isFinite(ended)&&began<=ended&&ended<=now+60000&&now-began<=86400000,'Fresh original build run required');
 const active=['resolve','build','deployment-hold'],skipped=['typecheck','migrations','runner-diagnostics','controller-tests','plan','test','browser','verify'];
 assert(jobs.length===active.length+skipped.length&&new Set(jobs.map(j=>j.name)).size===jobs.length&&new Set(jobs.map(j=>j.id)).size===jobs.length,'Exact build-only job inventory required');
 for(const j of jobs){assert(Number.isSafeInteger(j.id)&&j.id>0&&j.run_id===run.id&&j.head_sha===run.head_sha&&j.head_branch==='alpha'&&j.run_attempt===1&&j.status==='completed','Exact original build job identity required');assert(active.includes(j.name)?j.conclusion==='success':skipped.includes(j.name)&&j.conclusion==='skipped','Only build-only jobs may execute');if(active.includes(j.name))assert(Date.parse(j.started_at)>=began&&Date.parse(j.completed_at)>=Date.parse(j.started_at)&&Date.parse(j.completed_at)<=ended,'Build job chronology differs');}
 const resolve=jobs.find(j=>j.name==='resolve');assert(resolve.steps?.some(s=>s.name==='Refuse invalid build-only execution'&&s.conclusion==='success'),'Actual build-only admission guard must execute');
 const producer=jobs.find(j=>j.name==='build');assert(producer.steps?.some(s=>s.name==='Canonical System Testing production build and byte bundle'&&s.conclusion==='success')&&producer.steps?.some(s=>s.name==='Publish mandatory canonical build packet'&&s.conclusion==='success'),'Actual canonical build and packet must complete');
 assert(Array.isArray(artifacts)&&artifacts.length>=1&&artifacts.length<=2&&new Set(artifacts.map(a=>a.name)).size===artifacts.length,'Bounded exact build artifact inventory required');
 for(const a of artifacts){const w=a.workflow_run;assert([BUILD_ARTIFACT,NEXT_APPLICATION_STATE].includes(a.name)&&a.expired===false&&Number.isSafeInteger(a.id)&&a.id>0&&Number.isSafeInteger(a.size_in_bytes)&&a.size_in_bytes>0&&a.size_in_bytes<=(a.name===BUILD_ARTIFACT?BUILD_ZIP_MAX:64*1024**2)&&/^sha256:[a-f0-9]{64}$/.test(a.digest??''),'Build artifact boundary differs');assert(w?.id===run.id&&w.repository_id===REPOSITORY_ID&&w.head_repository_id===REPOSITORY_ID&&w.head_sha===run.head_sha&&w.head_branch==='alpha','Build artifact provenance differs');assert(Date.parse(a.created_at)>=Date.parse(producer.started_at)&&Date.parse(a.created_at)<=Date.parse(producer.completed_at)&&Date.parse(a.expires_at)>now,'Build artifact producer chronology differs');}
 assert(artifacts.filter(a=>a.name===BUILD_ARTIFACT).length===1,'Canonical build packet required');return {kind:'AUTHENTICATED_BUILD_ONLY_INVENTORY_NOT_TEST_COVERAGE',producer,artifact:artifacts.find(a=>a.name===BUILD_ARTIFACT),fullGatePassCreated:false,releaseAuthorized:false};
}

/** Ordinary byte-install authority from explicitly combined coverage, never a fake full CI PASS. */
export function createTypeRepairInstallGrant({acceptance,evidence,snapshot,baselineBuildId,environmentSha256,now=Date.now()}){
 const {acceptanceSha256,...body}=acceptance??{};
 assert(acceptanceSha256===installHash(installJson(body))&&body.kind==='COMBINED_REQUIRED_COVERAGE_WITH_ERASED_FIXTURE_REPAIR'&&body.policy==='type-only-test-fixture-repair/v1'&&body.result==='ACCEPTED_WITH_AUTHENTICATED_ORIGINAL_PASSES'&&body.releaseAuthorized===false&&body.fullGatePassCreated===false&&body.originalRunConclusion==='failure'&&body.originalCompilerConclusion==='failure'&&body.originalFinalVerifierConclusion==='failure'&&body.wholeCompiler?.conclusion==='success'&&body.retainedUnits?.length>0,'Explicit complete retained-coverage acceptance required');
 assert(evidence.kind==='AUTHENTICATED_CANONICAL_BUILD_ONLY_NOT_FULL_GATE'&&evidence.sha===body.candidate&&evidence.controller===evidence.sha&&evidence.controllerBranch==='alpha'&&evidence.build?.canonicalCandidateInputsVerified===true&&evidence.build.source===evidence.sha&&evidence.build.controller===evidence.controller&&evidence.build.runId===evidence.runId,'Exact fresh build-only source required');
 if(evidence.deploymentBaseline!==evidence.baseline){const proof=evidence.baselineAdvance,{proofSha256,...boundary}=proof??{};assert(proofSha256===installHash(installJson(boundary))&&boundary.kind==='FORWARD_STAGING_BASELINE_SOURCE_PREFIX_NOT_CI_RECEIPT'&&boundary.candidate===evidence.sha&&boundary.ciBaseline===evidence.baseline&&boundary.deploymentBaseline===evidence.deploymentBaseline&&boundary.originalCiBaselinePreserved===true&&boundary.releaseAuthorized===false,'Exact forward-baseline source prefix required');}
 const origin=inspectBuildOnlySnapshot({...snapshot,expected:{candidate:evidence.sha,controller:evidence.controller,runId:evidence.runId},now});
 assert(evidence.artifact.id===origin.artifact.id&&evidence.artifact.digest===origin.artifact.digest,'Fresh authenticated build artifact differs');
 const run=snapshot.run,producer=origin.producer;
 const witnessFingerprint=installHash(installJson({kind:'TYPE_ONLY_REPAIR_AND_NEW_CANONICAL_BUILD_INSTALL',acceptanceSha256,runId:run.id,controller:run.head_sha,source:evidence.sha,artifact:{id:origin.artifact.id,digest:origin.artifact.digest},buildProvenanceSha256:evidence.build.provenanceSha256}));
 const grant={format:1,kind:'OPERATOR_AUTHORIZED_STAGING_CI_BUILD_INSTALL',policyVersion:CI_POLICY,target:'alpha-staging',installId:randomUUID(),source:evidence.sha,controller:evidence.controller,controllerBranch:'alpha',baseline:evidence.deploymentBaseline,baselineBuildId,environmentSha256,runId:run.id,runAttempt:1,runCreatedAt:run.created_at,issuedAt:new Date(now).toISOString(),expiresAt:new Date(Math.min(now+30*60000,Date.parse(run.created_at)+86400000)).toISOString(),producerStartedAt:producer.started_at,producerCompletedAt:producer.completed_at,witnessFingerprint,artifact:{id:origin.artifact.id,digest:origin.artifact.digest},build:Object.fromEntries(INSTALL_BUILD_FIELDS.map(key=>[key,evidence.build[key]]))};
 return validateInstallGrant(grant,{now});
}
